using System;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public static class NWCancel {
 public static IEnumerator Run(NWProbe p){yield return p.Wait(()=>CP05Training.Instance?.Hero!=null,15);yield return p.Wait(()=>UnityEngine.Object.FindObjectsByType<Button>().Any(x=>x.name=="训练装备架"),5);var h=CP05Training.Instance.Hero;foreach(var e in CP05Training.Instance.Enemies)e.enabled=false;UnityEngine.Object.FindObjectsByType<Button>().Single(x=>x.name=="训练装备架").onClick.Invoke();yield return null;yield return null;var drop=UnityEngine.Object.FindObjectsByType<LootPickup>().Single(x=>x.Gear?.type==GearType.Greatsword);p.Check("cancel-real-pickup",drop.PickUp(h.Inventory));var c=h.GetComponent<AdventureCombat>();p.Check("cancel-real-equip",c.Gear.SelectMain(drop.Gear));yield return new WaitForSeconds(.3f);PlayerInput.Focus(true);yield return null;yield return null;p.Check("cancel-real-startup",c.UseSkill()&&h.GetComponent<FantasyActorVisual>().Motion=="Attack");c.CancelPending();p.Check("cancel-motor-cooldown",!c.NewWeapons.Busy&&c.SkillRemaining>0);p.Check("cancel-presentation-same-frame",h.GetComponent<FantasyActorVisual>().Motion!="Attack","existing action must not continue its old attack after actual request cancellation");yield return new WaitForSeconds(1.4f);p.Check("cancel-no-replay",!c.NewWeapons.Busy);}
}
